package com.mysms.privacy.mapper;

import com.mysms.privacy.api.model.AccessSummary;
import com.mysms.privacy.api.model.AccessSummaryActivity;
import com.mysms.privacy.api.model.AccessSummaryRecipient;
import com.mysms.privacy.model.AccessSummarySnapshot;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;

/**
 * Maps an access summary, generated now or kept on its fulfilled request, to the contract DTO. There is no way in: a
 * summary is generated by privacy from its own data, never taken from a client.
 */
@Mapper(config = PrivacyMapperConfig.class)
public interface AccessSummaryMapper {

    @Mapping(target = "subjectStatus",
            expression = "java(AccessSummary.SubjectStatusEnum.fromValue(summary.subjectStatus()))")
    AccessSummary toDto(AccessSummarySnapshot summary);

    @Mapping(target = "legalBasis",
            expression = "java(AccessSummaryActivity.LegalBasisEnum.fromValue(activity.legalBasis()))")
    AccessSummaryActivity toDto(AccessSummarySnapshot.Activity activity);

    AccessSummaryRecipient toDto(AccessSummarySnapshot.Recipient recipient);
}
